void setup() {
  Serial.begin(115200);
  Wire.begin();
  pinMode(SWPIN, INPUT);
  pinMode(LEDPIN, OUTPUT);
  // OLED เริ่มทำงาน
  if (!OLED.begin(0x3C, true)) {
    Serial.println("OLED not found!");
    while (1);
  }

  OLED.clearDisplay();
  OLED.setTextSize(1);
  OLED.setTextColor(SH110X_WHITE);
  OLED.setCursor(0, 0);
  OLED.println("Initializing...");
  OLED.display();

  // RTC เริ่มทำงาน
  if (!rtc.begin()) {
    OLED.clearDisplay();
    OLED.setCursor(0, 0);
    OLED.println("RTC not found!");
    OLED.display();
    while (1);
  }

  if (rtc.lostPower()) {
    Serial.println("RTC lost power, setting time!");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }

  // ตั้งค่า I/O
  pinMode(LEDPIN, OUTPUT);
  pinMode(SWPIN, INPUT_PULLUP);

  // เริ่มต้น DHT
  dht.begin();

  delay(1000);
}

void ShowTempHumid(){
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();
  OLED.setTextSize(1);
  OLED.setTextColor(SH110X_WHITE);
  OLED.setCursor(5, 55);
  OLED.print("Temp:");
  OLED.print(temperature, 1);
  OLED.print("C");
  OLED.setCursor(70, 55);
  OLED.print("Humid:");
  OLED.print(humidity, 0);
  OLED.print("%");
  OLED.display();
}

void ShowTimeDate(){ 
    DateTime now = rtc.now(); 

    // ล้างเฉพาะบริเวณเวลา
    OLED.fillRect(15, 10, 100, 20, SH110X_BLACK); // ล้างพื้นที่ HH:MM:SS

    OLED.setTextSize(2);
    OLED.setTextColor(SH110X_WHITE);
    OLED.setCursor(15, 10);
    if (now.hour() < 10) OLED.print('0');
    OLED.print(now.hour());
    OLED.print(':');
    if (now.minute() < 10) OLED.print('0');
    OLED.print(now.minute());
    OLED.print(':');
    if (now.second() < 10) OLED.print('0');
    OLED.print(now.second());

    // ล้างพื้นที่วันที่
    OLED.fillRect(35, 35, 60, 10, SH110X_BLACK);
    OLED.setTextSize(1);
    OLED.setCursor(35, 35);
    OLED.print(now.day());
    OLED.print('/');
    OLED.print(now.month());
    OLED.print('/');
    OLED.print(now.year());

    ShowTempHumid();  
}

void LEDon(){
  int SWState = digitalRead(SWPIN);
  if (SWState == HIGH){
	digitalWrite(LEDPIN, HIGH);
  } else {
	digitalWrite(LEDPIN, LOW);
  }
}

void loop() {
  OLED.clearDisplay();

  // 🔹 Step 1: เล่นอนิเมชันให้จบ
  for (int i = 0; i < epd_bitmap_allArray_LEN; i++) {
    OLED.clearDisplay();
    OLED.drawBitmap(
      (SCREEN_WIDTH - BMP_WIDTH) / 2,
      (SCREEN_HEIGHT - BMP_HEIGHT) / 2,
      epd_bitmap_allArray[i],
      BMP_WIDTH,
      BMP_HEIGHT,
      SH110X_WHITE
    );
    OLED.display();
    delay(50); // ความเร็วของเฟรม
    LEDon();  
  }

  // 🔹 Step 2: แสดงเวลาแบบเคลื่อนไหวจริง 5 วินาที
  unsigned long startTime = millis();  // บันทึกเวลาที่เริ่มแสดง
  while (millis() - startTime < 5000) { // วนลูป 5 วินาที
    OLED.clearDisplay();
    ShowTimeDate();   // ฟังก์ชันนี้ต้องอ่าน RTC ทุกครั้ง
    OLED.display();
    LEDon();
    delay(50);       // อัปเดตทุก 0.5 วินาที (หรือปรับได้)
  }

}
